"""settings.py 를 처음 상태로 되돌립니다.

쓰는 때: 값을 이것저것 바꾸다가 무엇이 원래 값이었는지 모르게 됐을 때.
쓰는 법: 터미널에서  python reset.py
결과:   settings.py 가 처음 배포 상태로 돌아갑니다(HISTORY_TURNS = 2 유지).
"""

import sys
# Windows 터미널은 한글을 cp949 로 그려서 안내문이 깨진다(260827 실측).
if sys.platform == "win32":
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")

ORIGINAL = "# ================================================================\n#  바꾸는 파일은 이것 하나입니다.  app.py 는 열지 않습니다.\n#\n#  바꾸는 법\n#    1) 아래 값을 고칩니다\n#    2) Ctrl + S 로 저장합니다\n#    3) 터미널에서 Ctrl + C 로 앱을 끕니다\n#    4) 명령어.txt 의 4번을 터미널에 다시 붙여 넣습니다\n#  저장만 하고 다시 켜지 않으면 화면은 그대로입니다.\n# ================================================================\n\n\n# ================================================================\n#                        turn 이 무엇인가\n# ================================================================\n#\n#  turn = 주고받기 한 번 = 내가 친 말 1개 + 봇이 한 답 1개.\n#\n#  내 말만도 아니고 봇 답만도 아닙니다.  둘이 붙어 있는 한 쌍입니다.\n#\n# ----------------------------------------------------------------\n#  실물로 봅니다.  아래는 WoS 데이터셋의 진짜 대화입니다.\n#  (wos_train_full.jsonl, guid = wos-v1_train_00001, 도메인 = 관광)\n# ----------------------------------------------------------------\n#\n#   turn 1  나  : \"쇼핑을 하려는데 서울 서쪽에 있을까요?\"\n#           봇  : \"서울 서쪽에 쇼핑이 가능한 곳이라면 노량진 수산물 도매시장이 있습니다.\"\n#\n#   turn 2  나  : \"오 네 거기 주소 좀 알려주세요.\"\n#           봇  : \"노량진 수산물 도매시장의 주소는 서울 동작구 93806입니다.\"\n#\n#   turn 3  나  : \"알려주시는김에 연락처랑 평점도 좀 알려주세요.\"\n#           봇  : \"그럼. 연락처는 6182006591이고 평점은 4점입니다.\"\n#\n#   turn 4  나  : \"와 감사합니다.\"\n#           봇  : \"감사합니다.\"\n#\n#  이 대화는 4 turn 입니다.  줄로 세면 8줄이지만 turn 으로 세면 4 입니다.\n#  화면에 보이는 말풍선 개수와 turn 개수는 다릅니다.  말풍선 8개 = turn 4개.\n#\n# ----------------------------------------------------------------\n#  코드에서 turn 은 어떻게 생겼나\n# ----------------------------------------------------------------\n#\n#  app.py 의 chat(message, history) 가 받는 history 는 이렇게 생겼습니다.\n#\n#      history = [\n#          (\"쇼핑을 하려는데 서울 서쪽에 있을까요?\", \"...노량진 수산물 도매시장이 있습니다.\"),\n#          (\"오 네 거기 주소 좀 알려주세요.\",        \"...서울 동작구 93806입니다.\"),\n#          (\"알려주시는김에 연락처랑 평점도...\",      \"...연락처는 6182006591이고 평점은 4점입니다.\"),\n#      ]\n#\n#  괄호 한 쌍이 turn 1개입니다.  len(history) 가 곧 지금까지의 turn 수입니다.\n#  위 예에서 len(history) == 3 이고, 지금 내가 \"와 감사합니다\" 를 치면\n#  그것이 message 로 따로 들어옵니다.  아직 history 에는 없습니다.\n#\n#      history  = 지나간 turn 들          (내 말 + 봇 답이 짝지어 저장됨)\n#      message  = 방금 친 말 하나          (아직 봇이 답을 안 했으니 짝이 없음)\n#\n# ----------------------------------------------------------------\n#  HISTORY_TURNS 는 그 짝을 뒤에서 몇 개 볼지 정합니다\n# ----------------------------------------------------------------\n#\n#      recent = history[-HISTORY_TURNS:]\n#\n#  HISTORY_TURNS = 2 이고 위 history(3개) 라면 recent 는 뒤에서 2개입니다.\n#\n#      recent = [ turn 2, turn 3 ]        <-- turn 1 은 빠집니다\n#\n#  turn 1 에서 내가 말한 \"쇼핑\" 과 \"서울 서쪽\" 은 봇에게 안 넘어갑니다.\n#  화면에는 그대로 보이는데 봇은 못 봅니다.  이것이 \"범위 밖으로 밀림\" 입니다.\n#\n#  WoS 원본 데이터는 이 문제가 없습니다.  turn 3 의 state 를 보면\n#\n#      [\"관광-종류-쇼핑\", \"관광-지역-서울 서쪽\", \"관광-이름-노량진 수산물 도매시장\"]\n#\n#  turn 1 에서 나온 \"쇼핑\" 과 \"서울 서쪽\" 이 turn 3 에도 그대로 있습니다.\n#  사람은 앞에 말한 것을 기억하니까요.\n#\n#  WoS 의 state 가 정답지이고, 내 봇의 \"채운 칸\" 이 내 답안입니다.\n#  둘이 어긋나는 지점을 찾는 것이 이번 주 과제입니다.\n#\n# ----------------------------------------------------------------\n#  주의 - 어제 본 \"넘긴 것: N개\" 는 turn 수가 아닙니다\n# ----------------------------------------------------------------\n#\n#  수업 중 실습 앱은 화면에 \"넘긴 것: N개\" 를 띄웠습니다.\n#  그 N 은 turn 수가 아니라 **모델에게 보낸 메시지 개수** 입니다.\n#\n#      turn 1개  ->  메시지 2개 (user 1 + model 1)\n#      거기에 방금 친 말 1개를 더한다\n#\n#      넘긴 것 = HISTORY_TURNS x 2 + 1\n#\n#      HISTORY_TURNS = 5  ->  넘긴 것 11개\n#      HISTORY_TURNS = 6  ->  넘긴 것 13개\n#      HISTORY_TURNS = 7  ->  넘긴 것 15개\n#\n#  홀수만 나오는 이유가 이것입니다.  마지막 +1 이 방금 친 말입니다.\n#  turn 을 7로 올렸는데 15가 뜬 것은 고장이 아니라 세는 단위가 달랐던 것입니다.\n#\n# ================================================================\n\n\n# ----------------------------------------------------------------\n#  1. 앞 대화를 몇 turn 까지 건널까요?\n#\n#     어제 랩의 USE_HISTORY 는 이 손잡이에 합쳐졌습니다.\n#     0 = 어제의 USE_HISTORY = False 와 같습니다 (하나도 안 건넴)\n#\n#     이 값은 2 로 고정입니다.  바꾸지 않습니다.\n#     2 = 바로 앞 두 번의 주고받기만 건넨다\n#\n#     이 제약 아래에서 필요한 칸을 다 받아내는 것이 오늘 과제입니다.\n# ----------------------------------------------------------------\nHISTORY_TURNS = 2\n\n\n# ----------------------------------------------------------------\n#  2. 어떻게 물어볼까요?\n#\n#     \"one_by_one\"  = 한 번에 한 칸씩 묻습니다\n#     \"all_at_once\" = 필요한 것을 한 번에 다 묻습니다\n#\n#     넣을 수 있는 값: \"one_by_one\" 또는 \"all_at_once\"  (따옴표 포함)\n#\n#     turn 과의 관계:\n#       one_by_one  으로 5칸을 채우려면 최소 5 turn 이 듭니다.\n#                   HISTORY_TURNS = 2 이면 1번 칸은 3 turn 째에 밀려납니다.\n#       all_at_once 는 1 turn 에 여러 칸이 들어옵니다.\n#                   같은 HISTORY_TURNS = 2 라도 살아남는 칸이 달라집니다.\n# ----------------------------------------------------------------\nASK_STYLE = \"one_by_one\"\n\n\n# ----------------------------------------------------------------\n#  3. 유저에게 물어서 채우는 칸\n#\n#     (칸 이름, 물어볼 말) 을 한 줄씩 적습니다.\n#     줄을 지우면 봇이 그 칸을 묻지 않습니다.\n#\n#     내 도메인의 칸 이름은 WoS 슬롯 목록에서 가져옵니다.\n#\n#       식당    지역 / 종류 / 가격대 / 예약 시간 / 예약 명수      (5칸)\n#       숙소    종류 / 가격대 / 숙박 기간 / 인터넷 / 주차          (5칸)\n#       관광    종류 / 지역 / 이름                                (3칸)\n#       택시    출발지 / 도착지 / 출발 시간 / 종류                 (4칸)\n#       지하철  출발역 / 도착역                                   (2칸)\n#\n#     아래는 관광 예시입니다.  자기 도메인으로 바꿔 쓰세요.\n# ----------------------------------------------------------------\nASK_SLOTS = [\n    (\"종류\", \"어떤 걸 하고 싶으세요? 쇼핑, 관람, 체험 중에서요.\"),\n    (\"지역\", \"서울 어느 쪽으로 찾아드릴까요?\"),\n    (\"이름\", \"가고 싶은 곳 이름이 정해져 있나요?\"),\n]\n\n\n# ----------------------------------------------------------------\n#  4. 묻지 않고 시스템이 채우는 칸\n#\n#     Flow diagram 4열에 \"시스템이 자동으로 준다\" 라고 적은 칸들입니다.\n#     유저에게 물을 필요가 없는 값.\n#\n#     아래는 관광 예시입니다.  자기 도메인으로 바꿔 쓰세요.\n# ----------------------------------------------------------------\nAUTO_SLOTS = {\n    \"주소\":   \"이름이 정해지면 자동 조회\",\n    \"연락처\": \"이름이 정해지면 자동 조회\",\n    \"평점\":   \"이름이 정해지면 자동 조회\",\n}\n"

open("settings.py", "w", encoding="utf-8").write(ORIGINAL)
print("settings.py 를 처음 상태로 되돌렸습니다.")
for _line in ORIGINAL.splitlines():
    _t = _line.strip()
    if _t.startswith("#") or "=" not in _t:
        continue
    _k, _v = _t.split("=", 1)
    _k, _v = _k.strip(), _v.strip()
    if not _k.isupper():
        continue
    if _v in ("[", "{", "("):
        print("  " + _k + " = (여러 줄, 파일에서 확인)")
    else:
        print("  " + _k + " = " + _v)
print("터미널에서 명령어.txt 의 4번을 터미널에 다시 붙여 넣으세요.")
